import{_ as t,H as o,f as a,i as n}from"./chunks/framework.CBmkDW73.js";const g=JSON.parse('{"title":"Best Practices","description":"","frontmatter":{},"headers":[],"relativePath":"guide/best-practices.md","filePath":"en/guide/best-practices.md"}'),s={name:"guide/best-practices.md"};function r(i,e,c,l,d,h){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h1><h2 id="specs" tabindex="-1">Specs <a class="header-anchor" href="#specs" aria-label="Permalink to &quot;Specs&quot;">​</a></h2><p><strong>Write declaratively, not narratively.</strong> Use sections like <code>contract:</code>, <code>invariant:</code>, <code>test:</code>, <code>failure:</code>, not numbered steps or prose. The agent reads fast and follows precise declarations.</p><p><strong>Close only decisions that affect implementation.</strong> Before handing off to <code>plan</code>, resolve: contract, data shape, failure modes, and test criteria. Leave philosophical debates and &quot;nice-to-haves&quot; in <code>deferred</code> or <code>Working notes</code>.</p><p><strong>Reference code by path, never paste it.</strong> Specs are decisions about what to build, not walkthroughs of how.</p><h2 id="plans" tabindex="-1">Plans <a class="header-anchor" href="#plans" aria-label="Permalink to &quot;Plans&quot;">​</a></h2><p><strong>Tasks are 30-60 minutes each.</strong> Atomic enough that the agent can reason about them. Too large and you lose visibility; too small and overhead kills momentum.</p><p><strong>Acceptance is executable.</strong> Every task&#39;s acceptance condition must be something a CI/human can verify: a test name, a command, or a script. Not vague, not aspirational.</p><p><strong>Mark <code>[parallel]</code> only when truly independent.</strong> Shared state, error handling, or contracts that aren&#39;t closed → tasks aren&#39;t parallel. Overmarking leads to broken merges.</p><h2 id="git-workflow" tabindex="-1">Git workflow <a class="header-anchor" href="#git-workflow" aria-label="Permalink to &quot;Git workflow&quot;">​</a></h2><p><strong>One commit per RED-GREEN-refactor cycle.</strong> Pushes your thinking into the history. Helps with debugging later.</p><p><strong>Sync docs after each cycle.</strong> Right before commit. If you wait, you&#39;ll forget what you changed and why.</p><p><strong>Use descriptive branch names.</strong> <code>feat/oauth-github</code>, not <code>feature1</code>. Helps you navigate when you have multiple worktrees.</p><h2 id="large-projects" tabindex="-1">Large projects <a class="header-anchor" href="#large-projects" aria-label="Permalink to &quot;Large projects&quot;">​</a></h2><p><strong>Use roadmap when ≥3 milestones.</strong> Don&#39;t try to plan them all upfront. <code>plan</code> only the current one, update stubs as you learn.</p><p><strong>Mark current milestone clearly.</strong> <code>← plan in detail now</code> on M1 signals intent. Move the marker after ship, before planning M2.</p><p><strong>Expect to revise milestones after M1.</strong> First milestone teaches you what the rest will cost. That&#39;s the point.</p><h2 id="debugging" tabindex="-1">Debugging <a class="header-anchor" href="#debugging" aria-label="Permalink to &quot;Debugging&quot;">​</a></h2><p><strong>Isolate first, hypothesize second.</strong> Narrow to the smallest repro. Cut code until symptom disappears. Only then ask &quot;why.&quot;</p><p><strong>Change one variable at a time.</strong> Parallel hypotheses are tempting but make it hard to know which change fixed it.</p><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><p><strong>Test the contract, not the implementation.</strong> If the contract says &quot;returns 200 on success,&quot; test that. Not &quot;calls X function&quot; or &quot;reads from database Y.&quot;</p><p><strong>No mocks of internals.</strong> Mock external boundaries: HTTP, DB, filesystem. Mock your own code only if the real version is slow or nondeterministic.</p><h2 id="when-to-abandon" tabindex="-1">When to abandon <a class="header-anchor" href="#when-to-abandon" aria-label="Permalink to &quot;When to abandon&quot;">​</a></h2><p><strong>If assumptions change materially, stop.</strong> Don&#39;t power through if the problem you&#39;re solving isn&#39;t the problem anymore. Record reason and learnings in working notes, then stop — no spec, no plan, no ship.</p><p><strong>If a milestone&#39;s goal shifts ≥50%, return to design.</strong> Don&#39;t extend the plan. Acknowledge the new direction and restart.</p><h2 id="documentation-sync" tabindex="-1">Documentation sync <a class="header-anchor" href="#documentation-sync" aria-label="Permalink to &quot;Documentation sync&quot;">​</a></h2><p><strong>Living docs are facts, staging docs are drafts.</strong> After <code>ship</code>, spec moves to living docs. Tests and comments in code stay current with both.</p><p><strong>README is the first spec.</strong> If it doesn&#39;t match the code, PRs fail review. Same rule applies to all public contracts.</p>',29)])])}const u=t(s,[["render",r]]);export{g as __pageData,u as default};
